type Product = { id: string; title: string; price: number; stock: number };

export function getField<T, K extends keyof T>(obj: T, key: K): T[keyof T] {
  return obj[key];
}

export function lineTotal(product: Product, qty: number): number {
  const price = getField(product, 'price');
  return price * qty;
}

export function label(product: Product): string {
  const title = getField(product, 'title');
  return title.toUpperCase();
}

type Tag = 'news' | 'sport' | 'tech';

type ListOf<T> = T extends unknown ? T[] : never;

type FilterState = {
  selected: ListOf<Tag>;
  updatedAt: number;
};

export function addTag(state: FilterState, tag: Tag): FilterState {
  if (state.selected.length >= 3) return state;
  return {
    selected: [...state.selected, tag],
    updatedAt: Date.now(),
  };
}

type Profile = { id: string; displayName: string; avatarUrl: string };

const API_URL = 'https://api.example.com/v2';

async function get<T>(path: string): Promise<T> {
  const res = await fetch(`${API_URL}${path}`);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return (await res.json()) as T;
}

export function loadProfile(id: string): Promise<Profile> {
  return get<Profile>(`/profiles/${id}`);
}

export function initials(profile: Profile): string {
  return profile.displayName.slice(0, 2).toUpperCase();
}
